internal static class GenerationPresetTests
{
    static void Check(bool v,string message){if(!v)throw new Exception(message);}
    static void Near(double a,double b,string message){Check(Math.Abs(a-b)<.00001,message+": "+a+" / "+b);}
    static EditorState Scene(Track t){var s=new EditorState{fps=50,duration=180,randomSeed=991,nativeTest=new NativeTestPosition{x=630,y=480},tracks=new List<Track>{t}};Motion.Normalize(s);return s;}
    static Track Source(string kind="object"){return new Track{id=Guid.NewGuid().ToString("N"),kind=kind,name="来源",sprite="sprCherry",x=220,y=140,start=10,end=65,lane=0,count=25,shape="star2",radius=90};}
    static object Rows(BulletWorld w){return w.bullets.Where(b=>b.birth<=w.Frame&&!b.dead).Select(b=>new{source=b.source.id,b.birth,b.index,b.generation,b.x,b.y,b.direction,b.speed,scale=b.scale*BulletLifetime.Scale(b),alpha=b.alpha*BulletLifetime.Alpha(b),trailMode=Trails.Mode(b.source),trailInterval=b.source.trailInterval,trailLife=b.source.trailLife,trailAlpha=b.source.trailStartAlpha,trailSpeed=b.source.trailSpeed,trailDirection=b.source.trailDirection,trailRandom=b.source.trailRandom,b.kinematic,b.clockShift,b.sourceX,b.sourceY,b.collision}).ToArray();}
    static object Get(object o,string name){return o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);}
    static void Set(object o,string name,object value){o.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).SetValue(o,value);}
    static object Call(object o,string name,params object[] args){return o.GetType().GetMethods(BindingFlags.Instance|BindingFlags.NonPublic).First(m=>m.Name==name&&m.GetParameters().Length==args.Length).Invoke(o,args);}
    static void RenderMenu(ContextMenuStrip menu,string path)
    {menu.CreateControl();menu.Size=menu.GetPreferredSize(Size.Empty);menu.PerformLayout();using(var image=new Bitmap(menu.Width,menu.Height)){menu.DrawToBitmap(image,new Rectangle(Point.Empty,menu.Size));image.Save(path);}}
    static void RenderControl(Control c,string path)
    {var parent=c.Parent;var dock=c.Dock;var bounds=c.Bounds;int index=parent.Controls.GetChildIndex(c);parent.Controls.Remove(c);using(var surface=new Panel{Size=new Size(590,650),BackColor=c.BackColor,Font=c.Font}){surface.Controls.Add(c);c.Dock=DockStyle.Fill;c.Visible=true;surface.CreateControl();surface.PerformLayout();c.CreateControl();c.PerformLayout();using(var image=new Bitmap(590,650)){surface.DrawToBitmap(image,new Rectangle(0,0,590,650));image.Save(path);}surface.Controls.Remove(c);}parent.Controls.Add(c);parent.Controls.SetChildIndex(c,index);c.Dock=dock;c.Bounds=bounds;}
    static void CheckPicking(string folder)
    {
        var back=Source();back.name="后层";back.lane=2;var front=Source("emitter");front.name="前层";front.lane=4;
        var hidden=Source();hidden.templateOnly=true;var future=Source();future.start=70;var disabled=Source();disabled.enabled=false;
        var state=Scene(back);state.tracks.AddRange(new[]{front,hidden,future,disabled});Motion.Normalize(state);
        var room=new RoomData();var instance=new RoomInstance{id="room-object",name="objCherry",x=220,y=140};room.instances.Add(instance);
        using(var sprites=new SpriteStore{Project=folder})using(var stage=new StageCanvas{State=state,Room=room,Sprites=sprites,Size=new Size(848,656),Frame=10}){
            stage.ObjectSprites[instance.name]="sprCherry";stage.CreateControl();stage.SelectedTrack=back;stage.SelectedTracks.Add(back);
            stage.SelectTrack=(t,k)=>{stage.SelectedTrack=t;stage.SelectedTracks.Clear();stage.SelectedTracks.Add(t);stage.SelectedInstance=null;};
            stage.SelectTracks=(tracks,t)=>{stage.SelectedTracks.Clear();stage.SelectedTracks.UnionWith(tracks);stage.SelectedTrack=t;};stage.SelectInstance=i=>{stage.SelectedInstance=i;stage.SelectedTracks.Clear();stage.SelectedTrack=null;};
            int begins=0,changes=0;stage.BeginEdit=()=>begins++;stage.Changed=()=>changes++;
            var hits=Call(stage,"PickTargets",new PointF(220,140));Check(((System.Collections.ICollection)hits).Count==3,"Overlap candidates include invisible templates or miss room instances");
            using(var menu=(ContextMenuStrip)Call(stage,"CreatePickMenu",hits,false)){
                Check(menu.Items.Count==5&&menu.Items[2].Text.Contains("前层")&&menu.Items[3].Text.Contains("轨道 3"),"Overlap menu lacks identity/lane/order");
                Check(menu.Renderer is DarkStripRenderer,"Overlap picker is not dark themed");((ToolStripMenuItem)menu.Items[3]).PerformClick();Check(stage.SelectedTrack==back,"Cannot select lower object");
                RenderMenu(menu,Path.Combine(folder,"overlap-picker-zh.png"));
                ((ToolStripMenuItem)menu.Items[4]).PerformClick();Check(stage.SelectedInstance==instance,"Cannot select underlying room instance");
            }
            stage.SelectTrack(back,null);using(var menu=(ContextMenuStrip)Call(stage,"CreatePickMenu",hits,true)){((ToolStripMenuItem)menu.Items[2]).PerformClick();Check(stage.SelectedTracks.SetEquals(new[]{front,back}),"Overlap picker broke additive selection");}
            using(var menu=(ContextMenuStrip)Call(stage,"CreatePickMenu",hits,false)){((ToolStripMenuItem)menu.Items[3]).PerformClick();Check(stage.SelectedTrack==back&&stage.SelectedTracks.SetEquals(new[]{back}),"Confirmed picker choice did not focus the chosen member of a multi-selection");}
            stage.SelectTrack(back,null);Call(stage,"OnMouseDown",new MouseEventArgs(MouseButtons.Left,1,244,164,0));Check(Get(stage,"pendingPicks")!=null&&stage.SelectedTrack==back&&begins==0,"Ambiguous click selected/edited before confirmation");stage.Capture=false;Call(stage,"OnMouseCaptureChanged",EventArgs.Empty);Check(Get(stage,"pendingPicks")==null&&stage.SelectedTrack==back,"Cancel changes selection");
            Call(stage,"OnMouseDown",new MouseEventArgs(MouseButtons.Left,1,244,164,0));Call(stage,"OnMouseMove",new MouseEventArgs(MouseButtons.Left,0,254,164,0));Call(stage,"OnMouseUp",new MouseEventArgs(MouseButtons.Left,1,254,164,0));Check(back.x==230&&front.x==220&&begins==1&&changes==1&&Get(stage,"pickMenu")==null,"Overlap picker blocked drag of selected object");
            stage.ViewZoom=2;stage.ViewX=50;stage.ViewY=-20;var screen=new[]{new PointF(220,140)};using(var matrix=(System.Drawing.Drawing2D.Matrix)Call(stage,"WorldDisplayMatrix"))matrix.TransformPoints(screen);var point=(PointF)Call(stage,"Position",Point.Round(screen[0]));Check(((System.Collections.ICollection)Call(stage,"PickTargets",point)).Count==3,"Overlap hit test ignores preview zoom/pan");
            stage.TemplatePreviewId=hidden.id;Check(((System.Collections.ICollection)Call(stage,"PickTargets",new PointF(220,140))).Count==2,"Local template preview cannot select its root");
            Language.Select(folder,"en");using(var menu=(ContextMenuStrip)Call(stage,"CreatePickMenu",hits,false)){Check(menu.Items[0].Text.StartsWith("Choose overlapping object")&&menu.Items[3].Text.Contains("Track 3")&&menu.Items[3].Text.Contains("后层"),"Picker translation changes names or misses labels");RenderMenu(menu,Path.Combine(folder,"overlap-picker-en.png"));}Language.Select(folder,"zh-CN");
        }
    }
