            {var source=Source();var s=Scene(source);var a=GenerationPresets.Apply(s,source,"random-360");var child=s.tracks.Single(t=>t.id==a.templateId);child.expressions["angle"]="random_range(30,150)";child.count=100;Motion.Normalize(s);var w=new BulletWorld(s);w.Seek(10);Check(w.bullets.All(b=>b.direction>=30&&b.direction<150)&&w.bullets.Select(b=>(int)((b.direction-30)/30)).Distinct().Count()==4,"Custom random range is not independent across bullets");child.expressions["angle"]="choose(0,90,180,270)";Motion.Normalize(s);w=new BulletWorld(s);w.Seek(10);Check(w.bullets.Select(b=>b.direction).Distinct().Count()==4,"Choose does not draw separately per bullet");}
            {var source=Source("rod");var s=Scene(source);var a=GenerationPresets.Apply(s,source,"random-360");a.spawnOrigin="each";var child=s.tracks.Single(t=>t.id==a.templateId);child.count=1;Motion.Normalize(s);var w=new BulletWorld(s);w.Seek(10);Check(w.bullets.Count==25&&w.bullets.Select(b=>Math.Round(b.direction,4)).Distinct().Count()==25,"Same-frame template instances share a direction draw");}
            {var source=Source("emitter");source.start=0;source.end=0;source.count=1;source.life=65;source.speed=1;var s=Scene(source);var a=GenerationPresets.Apply(s,source,"aim-player");a.spawnRepeat=20;Motion.Normalize(s);Check(source.bulletActions.Contains(a)&&!source.spawnActions.Contains(a),"Emitter generator must follow each bullet by default");var w=new BulletWorld(s);w.Seek(80);Check(w.bullets.Where(b=>b.generation==1).Select(b=>b.birth).Distinct().SequenceEqual(new[]{0,20,40,60}),"Mobile source did not repeat through its lifetime");Near(w.bullets.First(b=>b.generation==1&&b.birth==20).sourceX,240,"Mobile source origin did not follow flight");}
            var phase=new Track{id="phase",kind="variable",start=5,end=100,lane=0,variableName="phase",variableExpression="choose(0,90,180,270)",variableRepeat=10,variableDefault=7};
            var counter=new Track{id="counter",kind="variable",start=2,end=80,lane=0,variableName="counter",variableExpression="global.counter+floor(random_range(1,2))",variableRepeat=3,variableDefault=2};
            var distance=new Track{id="distance",kind="variable",start=3,end=3,lane=1,variableName="distance",variableExpression="floor(point_distance(0,0,3,4))+global.phase"};
            var state=Scene(Source());state.tracks.InsertRange(0,new[]{phase,counter,distance});Motion.Normalize(state);Near(GlobalVariables.At(state,0)["phase"],7,"Default before assignment");Near(GlobalVariables.At(state,8)["counter"],5,"Self-dependent interval assignment");Near(GlobalVariables.At(state,3)["distance"],12,"History and dependency order");var sample=GlobalVariables.At(state,65)["phase"];GlobalVariables.At(state,4);Near(GlobalVariables.At(state,65)["phase"],sample,"Old seek resampled random");
