            for(int i=0;i<5;i++){var source=Source(GenerationPresets.Formation(GenerationPresets.Keys[i])?"rod":"object");source.id="source"+i;source.x=100+i*125;source.y=180;fixture.tracks.Add(source);var action=GenerationPresets.Apply(fixture,source,GenerationPresets.Keys[i]);action.spawnRepeat=20;var target=fixture.tracks.Single(t=>t.id==action.templateId);target.id="template"+i;action.templateId=target.id;if(i==2)target.expressions["speed"]="2+global.counter/10";if(i==0){target.life=45;Trails.SetMode(target,"shrink-fade");target.bulletActions.Add(new BulletAction{type="turn",start=5,duration=0,to=.4});}if(i==1)target.lifetimeMode="room";if(i==2){target.lifetimeMode="view";target.deathEffect="fade";}if(i==3){target.life=60;Trails.SetMode(target,"custom");target.trailSpeed=1;target.trailDirection=15;target.trailRandom=true;}}
